    "Ты уже не участник, которого нужно развлекать, — ты становишься частью команды, которая делает лагерь. «Дрим-тим» — это молодой экипаж «Небо зовёт!»: настоящая ответственность, служение рядом со взрослыми и первый опыт работы в команде.": "You are no longer a participant who needs to be entertained — you become part of the team that makes the camp happen. The Dream Team is the young crew of “Heaven Is Calling!”: real responsibility, serving alongside adults, and your first experience of working in a team.",
    "На этой странице — полный текст внутреннего соглашения участника команды «Дрим-тим» и пример листа самооценки, чтобы вы могли ознакомиться с ними заранее. Это соглашение — не про запреты, а про честную договорённость: что ты получаешь и что берёшь на себя, присоединяясь к экипажу. Общие условия участия в лагере регулируются отдельным официальным договором, который подписывается дополнительно.": "This page contains the full text of the internal agreement for Dream Team members and a sample self-assessment sheet, so you can review them in advance. This agreement is not about restrictions — it is an honest arrangement: what you receive and what you take on when you join the crew. The general terms of camp participation are governed by a separate official contract signed additionally.",
