    "Служение — это и заметные роли, и совсем незаметные, вроде швабры и посуды. В этом и есть смысл: ты делаешь лагерь возможным наравне со взрослыми.": "Serving includes both visible roles and completely invisible ones, like the mop and the dishes. That is the whole point: you make the camp possible on equal footing with the adults.",
