    "Поддерживать и помогать в течение лагеря — ты не остаёшься один.": "Support and help you throughout the camp — you are not left alone.",
    "Честно и вовремя вернуть залог по итогам участия (см. раздел 4).": "Return your deposit honestly and on time based on your participation (see section 4).",
    "Выдать официальное рекомендательное письмо по итогам лагеря, которое можно использовать при поступлении на работу или учёбу.": "Issue an official letter of recommendation after the camp, which you can use when applying for a job or studies.",
    "4. Финансовые условия": "4. Financial terms",
    "Льготная ставка сотрудника — это привилегия, которую ты подтверждаешь тем, что реально в команде: приходишь и берёшь на себя свою часть. Чтобы закрепить договорённость, вся сумма вносится сразу как возвратный залог, а разница возвращается после лагеря. Это возврат заработанной скидки, а не штраф.": "The discounted staff rate is a privilege you confirm by genuinely being part of the team: showing up and taking on your share. To seal the arrangement, the full amount is paid upfront as a refundable deposit, and the difference is returned after the camp. It is the return of a discount you have earned — not a fine.",
