    "Пропуск по уважительной причине, о котором ты сообщил(а) заранее, на возврат не влияет.": "An absence for a valid reason that you reported in advance does not affect the refund.",
    "На возврат влияет только систематический пропуск без причины или отказ от заданий — и то сначала будет разговор с наставником и возможность выправиться, а не молчаливое удержание.": "Only repeatedly missing without a reason or refusing tasks affects the refund — and even then there will first be a conversation with a mentor and a chance to put things right, not a silent deduction.",
    "Если договорённость всё же не выполнена, участие засчитывается по обычной ставке участника. Это не штраф: ты оплачиваешь участие как обычный участник лагеря.": "If the arrangement is still not fulfilled, your participation is counted at the regular participant rate. This is not a fine: you simply pay for the camp as a regular participant.",
    "Возвратная сумма выдаётся в последний день лагеря.": "The refundable amount is paid out on the last day of the camp.",
    "5. Самооценка и рост": "5. Self-assessment and growth",
    "Каждый день ты сам(а) честно оцениваешь свой день — участие, задания, отношения — в личном листе самооценки. Это инструмент твоего роста, а не проверка: его никто не оценивает за тебя, и с оплатой он не связан.": "Every day you honestly assess your own day — participation, tasks, relationships — in your personal self-assessment sheet. It is a tool for your growth, not an inspection: nobody grades it for you, and it is not linked to payment.",
    "Экипаж держит для себя планку — средняя самооценка 7 и выше. Это наш общий ориентир и повод для честного разговора с собой, а не условие возврата залога.": "The crew keeps a bar for itself — an average self-assessment of 7 or higher. It is our shared reference point and a reason for an honest talk with yourself, not a condition for the deposit refund.",
    "Пример листа самооценки — ниже на этой странице.": "A sample self-assessment sheet is below on this page.",
    "6. Соглашение и официальный договор": "6. This agreement and the official contract",
