    "Все прочие условия участия (общие правила, оплата, безопасность, ответственность, обработка персональных данных) регулируются отдельным официальным подписанным договором.": "All other terms of participation (general rules, payment, safety, liability, personal data processing) are governed by a separate officially signed contract.",
    "При отказе от участия до начала лагеря возврат внесённой суммы производится по договорённости с организаторами в зависимости от сроков отказа.": "If you withdraw before the camp begins, the amount paid is refunded by arrangement with the organisers depending on when you withdraw.",
