    "Это лист для тебя. Его никто не проверяет, и с оплатой он не связан. Экипаж держит планку 7+ — это наш ориентир.": "This sheet is for you. Nobody checks it, and it is not linked to payment. The crew keeps a bar of 7+ — that is our reference point.",
