    "Вы помогаете другим — и получаете поддержку сами. Проект работает в обоих направлениях.": "Вы помогаете другим — и получаете поддержку сами. Проект работает в обоих направлениях.",
    "Откуда название Rosetto?": "Откуда название Rosetto?",
    "Проект назван в честь Розето, Пенсильвания — городка, где сила общины заменяла лекарства.": "Проект назван в честь Розето, Пенсильвания — городка, где сила общины заменяла лекарства.",
    "Стать участником Rosetto": "Стать участником Rosetto",
