    "Большинство проблем в жизни решаемы — сложно другое: понять, к кому обратиться, и успеть сделать это вовремя. Rosetto убирает именно этот шаг.": "Большинство проблем в жизни решаемы — сложно другое: понять, к кому обратиться, и успеть сделать это вовремя. Rosetto убирает именно этот шаг.",
