    "Читать историю Розето": "Читать историю Розето",
    "Уже участвуете в проекте взаимопомощи? Запросы о помощи по-прежнему создаются в приложении Rosetto — планы участия его дополняют, а не заменяют.": "Уже участвуете в проекте взаимопомощи? Запросы о помощи по-прежнему создаются в приложении Rosetto — планы участия его дополняют, а не заменяют.",
