    "команда «Дрим-тим» · «Небо зовёт!» — пример для ознакомления": "komanda “Dream Team” · “Debesis sauc!” — paraugs iepazīšanai",
    "Честно оцени свой день сам(а) по шкале 0–10. Это твой личный инструмент роста — не проверка и не условие оплаты. Смотришь на три вещи:": "Godīgi novērtē savu dienu pats/pati skalā no 0 līdz 10. Tas ir tavs personīgais izaugsmes rīks — ne pārbaude un ne apmaksas nosacījums. Tu skaties uz trim lietām:",
    "участие · задания · пример в отношениях.": "dalība · uzdevumi · piemērs attiecībās.",
