    "П1–П4 — планёрки до лагеря, Д1–Д7 — дни лагеря.": "П1–П4 — plānošanas sanāksmes pirms nometnes, Д1–Д7 — nometnes dienas.",
    "Шкала (0–10): как честно оценить себя": "Skala (0–10): kā godīgi novērtēt sevi",
    "выдающийся день: инициатива, помог другим, был отличным примером": "izcila diena: iniciatīva, palīdzēji citiem, biji lielisks piemērs",
    "норма экипажа: пришёл, включился, выполнил, держался хорошо — обычный хороший день": "apkalpes norma: atnāci, iesaistījies, izpildīji, turējies labi — parasta laba diena",
    "были шероховатости (опоздал, отвлёкся, задание сделал частично)": "bija nepilnības (nokavēji, novērsies, uzdevumu izpildīji daļēji)",
    "день не задался — есть над чем подумать": "diena neizdevās — ir par ko padomāt",
    "почти не включился или нарушил договорённости": "gandrīz neiesaistījies vai pārkāpi norunas",
    "Три вопроса к себе за день": "Trīs jautājumi sev dienas beigās",
    "— был(а) ли я включён(а), не отсиживался(ась) в стороне?": "— vai es biju iesaistīts(-a), nevis sēdēju malā?",
    "— сделал(а) ли то, что взял(а) на себя?": "— vai izdarīju to, ko uzņēmos?",
    "— был(а) ли примером в словах и отношении к другим?": "— vai biju piemērs vārdos un attieksmē pret citiem?",
    "Это лист для тебя. Его никто не проверяет, и с оплатой он не связан. Экипаж держит планку 7+ — это наш ориентир.": "Šī lapa ir tev. Neviens to nepārbauda, un ar apmaksu tā nav saistīta. Apkalpe tur latiņu 7+ — tas ir mūsu orientieris.",
