      "Gultas veļa (komplektu var iznomāt uz vietas par 5 eiro, paziņojiet iepriekš, ja tas nepieciešams)",
    "Экстра одеяло (или тёплое одеяло) - некоторые ночи могут быть прохладными":
      "Papildu sega (vai silta sega) — dažas naktis var būt vēsas",
