    "Шампунь / гель для душа": "Šampūns / dušas želeja",
    "Утром, на тихом часу и вечером во время планерок сотрудников у нас в лагере посменный патруль, чтобы обеспечить безопасный отдых.":
      "No rīta, klusās stundas laikā un vakarā darbinieku plānošanas sapulču laikā mūsu nometnē ir maiņu patruļa, lai nodrošinātu drošu atpūtu.",
    "Шутки, пранки, разукрашивания себя и других, прятание вещей, обзывательства, издевательства":
      "Joki, palaidnības, sevis un citu izkrāsošana, lietu slēpšana, apvainojumi, ņirgāšanās",
    "Пятница, 15 августа, 13:30 - 16:00. Утром программа по расписанию":
      "Piektdiena, 15. augusts, 13:30 – 16:00. No rīta programma pēc grafika",
