    "Для этой роли обучение ещё не опубликовано. Мы сообщим, когда оно появится.": "Šai lomai apmācība vēl nav publicēta. Mēs paziņosim, kad tā būs pieejama.",
    "Программа обновилась, и срок прошлой попытки истёк. Можно начать заново.": "Programma ir atjaunināta, un iepriekšējā mēģinājuma termiņš ir beidzies. Var sākt no jauna.",
