    "Сначала откройте и подтвердите материал.": "Vispirms atveriet un apstipriniet materiālu.",
    "Обучение пройдено!": "Apmācība pabeigta!",
    "Срок этой попытки истёк. Начните обучение заново.": "Šī mēģinājuma termiņš ir beidzies. Sāciet apmācību no jauna.",
    "Эта попытка закрыта.": "Šis mēģinājums ir slēgts.",
    "Программа обновилась. Завершите эту попытку до": "Programma ir atjaunināta. Pabeidziet šo mēģinājumu līdz",
    "Ответить": "Atbildēt",
    "Ответ не отправлен. Проверьте связь и попробуйте ещё раз.": "Atbilde netika nosūtīta. Pārbaudiet savienojumu un mēģiniet vēlreiz.",
