    "Обучение обновилось. Посмотрите, что изменилось.": "Apmācība ir atjaunināta. Apskatiet, kas ir mainījies.",
    "Этот тип вопроса пока не поддерживается. Обновите приложение или откройте обучение позже.": "Šis jautājuma veids pagaidām netiek atbalstīts. Atjauniniet lietotni vai atveriet apmācību vēlāk.",
    // P3: role learning — multi_select & swipe_binary controls
    "Выберите все подходящие варианты": "Izvēlieties visus atbilstošos variantus",
    "Ответ засчитывается, только если выбраны все верные варианты и ничего лишнего.": "Atbilde tiek ieskaitīta tikai tad, ja izvēlēti visi pareizie varianti un nekas lieks.",
