    "Проверьте выбранные варианты ответа.": "Pārbaudiet izvēlētos atbildes variantus.",
    "Проведите карточку влево или вправо — или выберите вариант кнопкой.": "Velciet kartīti pa kreisi vai pa labi — vai izvēlieties variantu ar pogu.",
