    "Мы получили вашу заявку на участие в лагере.": "Esam saņēmuši jūsu pieteikumu dalībai nometnē.",
    "Копию этой информации мы отправили на вашу электронную почту:": "Šīs informācijas kopiju nosūtījām arī uz jūsu e-pastu:",
    "В ближайшее время вышлем договор для подписания на вашу электронную почту:": "Tuvākajā laikā nosūtīsim līgumu parakstīšanai uz jūsu e-pastu:",
    "Бумажный договор будет подготовлен для подписания в лагере (+€10).": "Papīra līgums tiks sagatavots parakstīšanai nometnē (+€10).",
