      "Наша команда розгляне вашу заявку та зв'яжеться з вами найближчим часом. Поки ви чекаєте, ви можете ознайомитися з інформацією для батьків.",
    "Указание в форме регистрации если есть ли прививка от энцефалита - необходимо, чтобы знать как действовать в редком случае":
      "Зазначення у формі реєстрації, чи є щеплення від енцефаліту — необхідно, щоб знати, як діяти у рідкісному випадку",
