    "Утром, на тихом часу и вечером во время планерок сотрудников у нас в лагере посменный патруль, чтобы обеспечить безопасный отдых.":
      "Вранці, під час тихої години та ввечері під час планерок співробітників у нас у таборі позмінний патруль, щоб забезпечити безпечний відпочинок.",
