    "Разрядился аккумулятор, пробито колесо, закрылась машина — вызов лицензированной службы, услуги которой мы закупаем оптом, по тарифу для участников.": "Розрядився акумулятор, пробито колесо, зачинилася машина — виклик ліцензованої служби, послуги якої ми закуповуємо оптом, за тарифом для учасників.",
