    "Скажите координатору и поставьте оценку в приложении. Мы смотрим на реальные оценки участников по каждому поставщику: если качество стабильно не дотягивает до требований договора, мы меняем поставщика. Именно в этом смысл коллективной закупки — у одного клиента такой переговорной силы нет, у общины есть.": "Скажіть координатору і поставте оцінку в застосунку. Ми дивимося на реальні оцінки учасників щодо кожного постачальника: якщо якість стабільно не дотягує до вимог договору, ми змінюємо постачальника. Саме в цьому сенс колективної закупівлі — в одного клієнта такої переговорної сили немає, у спільноти є.",
