    "Приложение закрывает всё, что можно заказать. Но не всё решается заказом: подвезти, забрать, встретить, передать вещи, посидеть с детьми. Для этого в приложении есть запрос о помощи: вы описываете, что нужно, и делитесь геолокацией — запрос видят участники рядом, и откликается тот, кому по пути. Никто никому не обязан: помогает тот, у кого есть возможность.": "Застосунок закриває все, що можна замовити. Але не все вирішується замовленням: підвезти, забрати, зустріти, передати речі, посидіти з дітьми. Для цього в застосунку є запит про допомогу: ви описуєте, що потрібно, і ділитеся геолокацією — запит бачать учасники поруч, і відгукується той, кому по дорозі. Ніхто нікому не зобов'язаний: допомагає той, у кого є можливість.",
    "Попросить о помощи с геолокацией — откликнется тот, кому по пути": "Попросити про допомогу з геолокацією — відгукнеться той, кому по дорозі",
