// Provider component
// Keep the address bar and the NEXT_LOCALE cookie in step with the chosen
// language, so /lv, /en... links are shareable and the server renders the
// same language the client shows.
function syncLanguageUrl(lang: Language) {
  document.cookie = `NEXT_LOCALE=${lang}; path=/; max-age=31536000; samesite=lax`
  const { pathname, search, hash } = window.location
  const stripped = pathname.replace(/^\/(ru|en|lv|uk|ukr)(?=\/|$)/i, "") || "/"
  const prefixed = `/${lang}${stripped === "/" ? "" : stripped}`
  if (pathname !== prefixed) {
    window.history.replaceState(window.history.state, "", `${prefixed}${search}${hash}`)
  }
}

export function LanguageProvider({ children }: { children: ReactNode }) {
  // Initialize with default language
  const [language, setLanguageState] = useState<Language>("ru")
  const [showLanguageModal, setShowLanguageModal] = useState(false)
  const [isClient, setIsClient] = useState(false)

  // Set language and save to localStorage
  const setLanguage = (lang: Language) => {
    setLanguageState(lang)
    if (typeof window !== "undefined") {
      localStorage.setItem("preferredLanguage", lang)
      // A real navigation to the prefixed URL: the middleware stamps the
      // cookie and the whole page re-renders in the chosen language.
      document.cookie = `NEXT_LOCALE=${lang}; path=/; max-age=31536000; samesite=lax`
      const { pathname, search, hash } = window.location
      const stripped = pathname.replace(/^\/(ru|en|lv|uk|ukr)(?=\/|$)/i, "") || "/"
      const prefixed = `/${lang}${stripped === "/" ? "" : stripped}`
      if (pathname !== prefixed) {
        window.location.assign(`${prefixed}${search}${hash}`)
      } else {
        window.location.reload()
      }
    }
  }

  // Initialize on client-side only
  useEffect(() => {
    setIsClient(true)

    const isSupported = (lang: string | null | undefined): lang is Language =>
      Boolean(lang) && Object.keys(translationData).includes(lang as string)

    // 1. A /ru|/en|/lv|/uk|/ukr deep link states the language outright
    const prefix = window.location.pathname.match(/^\/(ru|en|lv|uk|ukr)(?:\/|$)/i)
    const prefixed = prefix ? prefix[1].toLowerCase() : null
    const urlLanguage = prefixed === "ukr" ? "uk" : prefixed

    if (isSupported(urlLanguage)) {
      setLanguageState(urlLanguage)
      localStorage.setItem("preferredLanguage", urlLanguage)
      syncLanguageUrl(urlLanguage)
      setShowLanguageModal(false)
      return
    }

    // 2. The cookie the middleware left behind on an earlier prefixed visit
    const cookieLanguage = document.cookie.match(/(?:^|;\s*)NEXT_LOCALE=([^;]*)/)?.[1]
    if (isSupported(cookieLanguage)) {
      setLanguageState(cookieLanguage)
      setShowLanguageModal(false)
      return
    }

    const savedLanguage = localStorage.getItem("preferredLanguage") as Language | null

    if (savedLanguage && Object.keys(translationData).includes(savedLanguage)) {
      setLanguageState(savedLanguage)
      setShowLanguageModal(false)
    } else {
      // Try to detect browser language
      const browserLang = navigator.language.split("-")[0]
      const mappedLang = {
        en: "en",
        ru: "ru",
        lv: "lv",
        uk: "uk",
      }[browserLang] as Language

      if (mappedLang) {
        setLanguageState(mappedLang)
      }

      // Still show the modal on first visit
      setShowLanguageModal(true)
    }
  }, [])

  // Get translations for the current language with fallback
  const translations = isClient ? translationData[language] || translationData.ru : translationData.ru

  const value: LanguageContextType = {
    language,
    setLanguage,
    translations,
    showLanguageModal,
    setShowLanguageModal,
  }

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>
}

// Hook to use the language context
export function useLanguage() {
  const context = useContext(LanguageContext)
  if (context === undefined) {
    // Return default context if used outside provider
    return defaultContext
  }
  return context
}
